import {addonPage,addonDetailPage} from './addon-ui.js';
import {timeField,timeLabel,timeQuery} from './time-control.js';
import {esc,icon,logo,button,link,field,password,head,empty,badge,date,short,metric,select,panel,note,table,errors,submit,authFrame,shell} from './view.js';
import {adminDashboard,adminTeams,adminOperations,competitionTools} from './admin-ui.js';
import {rulesetField,botRulesetField} from './experimental-ui.js';
import {standingsChart} from './standings.js';
import {renderRules} from './rules.js';
import {renderBotGuide} from './bot-guide.js';
import {resultLabel,policyLabel,sideName,resultReasons,jobErrorExplanation} from './result.js';

const subName=(s,id)=>s.submissions.find(x=>x.id===id)?.version||short(id);
const teamName=(s,id)=>s.competition?.entries.find(x=>x.team_id===id)?.name||short(id);
const form=(id,body)=>`<form id="${id}" class="real-form">${body}${errors()}</form>`;
const stats=items=>`<div class="stats-grid">${items.map(([label,value,ico,foot=''])=>`<div class="stat"><p class="stat-label">${esc(label)}</p><div class="stat-value">${esc(value)}</div><p class="stat-foot">${esc(foot)}</p></div>`).join('')}</div>`;
const authTabs=route=>`<nav class="real-auth-tabs"><a class="${route==='login'?'active':''}" href="#/login">Đăng nhập</a><a class="${route==='register'?'active':''}" href="#/register">Đăng ký đội</a></nav>`;
export function authPage(s) {
  if(s.route==='login') return authFrame(`<h2>Đăng nhập</h2><p>Dùng tài khoản được ban tổ chức cấp cho đội của bạn.</p>${authTabs('login')}${form('login-form',field('Tên đăng nhập','username','required autocomplete="username" maxlength="30"')+password('Mật khẩu','login-password')+submit('Đăng nhập'))}<a class="text-link" href="#/recover">Cần cấp lại mật khẩu? ${icon('arrow')}</a>${note('Chưa có tài khoản? Gửi hồ sơ đăng ký đội. Ban tổ chức sẽ duyệt và phát mật khẩu tạm.')}<a href="#/home" class="text-link">Về trang chủ</a>`);
  if(s.route==='recover') return authFrame(`<h2>Cấp lại mật khẩu</h2><p>Gửi mã tài khoản và email đội trưởng đã đăng ký để ban tổ chức kiểm tra.</p>${s.recoverySent?note('Đã ghi nhận yêu cầu. Nếu thông tin khớp, ban tổ chức sẽ kiểm tra và cấp mật khẩu tạm qua kênh của giải.'):form('recovery-form',field('Tên đăng nhập','username','required maxlength="30"')+field('Email đội trưởng','email','required maxlength="120"','email')+submit('Gửi yêu cầu'))}<a href="#/login" class="text-link">Quay lại đăng nhập ${icon('arrow')}</a>`);
  if(s.route==='change-password') return authFrame(`<h2>${s.user?.must_change_password?'Đổi mật khẩu tạm':'Đổi mật khẩu'}</h2><p>${s.user?.must_change_password?'Hoàn tất bước này để vào trang quản lý đội.':'Sau khi đổi, các phiên cũ sẽ được đăng xuất.'}</p>${form('password-form',password('Mật khẩu hiện tại / mật khẩu tạm','current-password')+password('Mật khẩu mới (8–128 ký tự)','new-password','new-password')+password('Nhập lại mật khẩu mới','confirm-password','new-password')+submit('Lưu mật khẩu mới'))}${s.user?.must_change_password?button('Đăng xuất','logout'):link('home','Về tổng quan')}`);
  if(s.registrationReceipt) return authFrame(`<h2>Đã gửi hồ sơ đăng ký</h2>${note('Ban tổ chức sẽ duyệt hồ sơ và cấp tài khoản cho đội.')}<dl class="detail-list"><div><dt>Mã hồ sơ</dt><dd class="mono">${esc(s.registrationReceipt.id)}</dd></div><div><dt>Trạng thái</dt><dd>${badge('pending','Chờ duyệt')}</dd></div></dl>${link('login','Về đăng nhập','primary')}`);
  const d=s.registrationDraft||{team:'',email:'',phone:'',members:Array.from({length:3},()=>({name:'',student_id:''}))};
  return authFrame(`<h2>Đăng ký đội</h2><p>Đăng ký 3–4 thành viên. Ban tổ chức duyệt hồ sơ và cấp tài khoản cho đội.</p>${authTabs('register')}${form('registration-form',field('Tên đội','team','required minlength="2" maxlength="40"','text',d.team)+`<div class="form-grid">${field('Email đội trưởng','email','required maxlength="120"','email',d.email)}${field('Số điện thoại (tùy chọn)','phone','maxlength="20"','tel',d.phone)}</div><div class="section-head"><h3>Thành viên <span class="muted">${d.members.length}/4</span></h3>${d.members.length<4?button('Thêm người thứ 4','add-member'):button('Bỏ người thứ 4','remove-member')}</div>`+d.members.map((m,i)=>`<fieldset class="member-field"><legend>${i===0?'Đội trưởng':'Thành viên '+(i+1)}</legend><div class="form-grid">${field('Họ và tên',`name-${i}`,'required minlength="2" maxlength="60"','text',m.name)}${field('Mã sinh viên',`student-${i}`,'required pattern="[A-Za-z0-9]{6,15}"','text',m.student_id)}</div></fieldset>`).join('')+`<label class="check-field"><input type="checkbox" name="confirmed" required>Đội xác nhận thông tin chính xác và đồng ý luật thi đấu OTTv2.</label>`+submit('Gửi hồ sơ đăng ký'))}<a href="#/home" class="text-link">Về trang chủ</a>`);
}

function compCards(s) {
  const items=s.competitions.filter(c=>!!c.archived_ms===!!s.competitionArchived);
  return items.length?`<div class="real-card-grid">${items.map(c=>`<article class="real-card" data-key="competition-${c.id}"><div class="section-head">${badge(c.archived_ms?'aborted':c.status,c.archived_ms?'Đã lưu trữ':undefined)}<span class="muted">${timeLabel(c.config.profile)}</span></div><h3>${esc(c.title)}</h3>${c.config.ruleset?badge('attention','Ruleset add-on'):''}<p>Vòng tròn hai lượt · Tối đa ${c.config.max_teams} đội</p><div class="table-actions">${link('competitions/'+c.id,'Mở giải đấu','small')}${s.user?.role==='admin'?competitionTools(c):''}</div></article>`).join('')}</div>`:empty(s.competitionArchived?'Chưa có giải đã xóa':'Chưa có giải đấu','Các giải sẽ xuất hiện tại đây khi ban tổ chức tạo giải.');
}
function home(s) {
  if(s.user?.role==='admin')return adminDashboard(s);
  if(!s.user) return `${head('UET Bot Arena','Nền tảng thi đấu bot OTTv2 dành cho sinh viên.',link('register','Đăng ký đội','primary'))}<section class="guest-intro"><div><h2>Thi đấu trên bàn cờ 9×9</h2><p>Các đội nộp bot C++17 để thi đấu theo luật OTTv2. Bạn có thể xem lịch, bảng xếp hạng và trận đấu mà không cần tài khoản.</p></div><div class="page-actions">${link('live','Xem trận không cần đăng nhập','primary')}${link('guide','Luật chơi & hướng dẫn')}</div></section>${panel('Giải đấu công khai',compCards(s),link('schedule','Xem lịch đấu','small'))}<ol class="onboarding">${[['Đăng ký đội','Gửi hồ sơ 3–4 thành viên để ban tổ chức duyệt và cấp tài khoản.'],['Nộp và thử bot','Tải SDK, nộp source C++ rồi chạy benchmark.'],['Tham gia giải','Chọn phiên bản bot đủ điều kiện trước khi ban tổ chức chốt lịch.']].map(([title,text],i)=>`<li><span>${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></li>`).join('')}</ol>`;
  const admin=s.user.role==='admin', d=s.dashboard||{};
  return `${head('Tổng quan',s.team?.name?'Đội '+s.team.name:'Thông tin giải đấu và hoạt động của đội.',admin?link('admin','Duyệt đội thi','primary'):link('submissions','Nộp phiên bản bot','primary'))}${admin?stats([['ĐỘI THAM GIA',d.teams||0,'users'],['HỒ SƠ CHỜ DUYỆT',d.pending_registrations||0,'file'],['GIẢI ĐẤU',d.competitions||0,'trophy'],['Tác vụ đang chạy',d.active_jobs||0,'code']]):stats([['Phiên bản bot',d.counts?.submissions||0,'upload'],['Benchmark',d.counts?.benchmarks||0,'code'],['Trận luyện tập',d.counts?.matches||0,'play'],['Tác vụ đang chạy',d.counts?.active_jobs||0,'clock']])}<div class="section-head"><div><h2>Giải đấu</h2></div>${link('competitions','Xem tất cả')}</div>${compCards(s)}${!admin?panel('Hoạt động gần đây',jobTable(s,s.jobs.slice(0,5))):note('Duyệt hồ sơ đội trước, sau đó mở giải để các đội chọn bot đã benchmark. Chốt lịch khi đủ đội và bắt đầu giải.')}`;
}
export function jobTable(s,jobs) {
  return jobs.length?table(['Tác vụ','Loại','Trạng thái','Tạo lúc',''],jobs.map(j=>`<tr data-key="job-${j.id}"><td class="mono">${short(j.id)}</td><td>${j.kind==='benchmark'?'Benchmark':'Luyện tập'}</td><td>${badge(j.status)}</td><td>${date(j.created_unix_ms)}</td><td>${link('jobs/'+j.id,'Chi tiết','small')}</td></tr>`)):empty('Chưa có tác vụ','Kết quả benchmark và luyện tập sẽ xuất hiện tại đây.');
}
function submissions(s) {
  return `${head('Nộp bot','Nộp source C++17 trong tệp ZIP. Mỗi phiên bản đã nộp được giữ nguyên.',button('Tải starter OTTv2','starter','','primary')+button('SDK v3 add-on','experimental-starter'))}<div class="real-two-col">${panel('Phiên bản mới',form('submission-form',field('Phiên bản','version','required placeholder="v1.0.0" pattern="v?[0-9]+[.][0-9]+[.][0-9]+(-[A-Za-z0-9.-]+)?"')+`<label class="field"><span>SDK / giao thức bot</span>${select('protocol_version',[['2','OTT v2 tiêu chuẩn · SDK v2'],['3','Ruleset add-on · SDK v3']])}</label><label class="field"><span>Source ZIP (tối đa 10 MiB)</span><input class="input file-input" type="file" name="source" accept=".zip,application/zip" required><small>ZIP phẳng, bot.cpp ở thư mục gốc. Chỉ nộp source/header, không nộp binary.</small></label>`+note('Source được biên dịch trong worker cô lập. Sau khi nộp, chạy benchmark để kiểm tra protocol và hiệu năng.')+submit('Nộp source C++')))}${panel('Phiên bản đã nộp',s.submissions.length?table(['Phiên bản','Mã','Nộp lúc',''],s.submissions.map(x=>`<tr><td><strong>${esc(x.version)}</strong><div class="muted">C++17 · SDK v${x.protocol_version||2}</div></td><td class="mono">${short(x.id)}</td><td>${date(x.created_unix_ms)}</td><td>${link('benchmark?submission='+x.id,'Benchmark','small')}</td></tr>`)):empty('Chưa có phiên bản','Tải starter OTTv2 và nộp gói ZIP đầu tiên.'))}</div>`;
}
function benchmark(s) {
  return `${head('Test & benchmark','Đo bot của đội trên worker: 24 trạng thái × 3 lần, tổng 72 mẫu.')}${panel('Chạy benchmark',s.submissions.length?form('benchmark-form',`<div class="form-grid"><label class="field"><span>Phiên bản</span>${select('submission_id',s.submissions.map(x=>[x.id,x.version+' · SDK v'+(x.protocol_version||2)]),s.selectedSubmission)}</label>${timeField(s.selectedMatch?{match_ms:Number(s.selectedMatch)}:s.selectedTurn?{turn_ms:Number(s.selectedTurn)}:s.competition?.config.profile)}</div>`+botRulesetField(s,[s.selectedSubmission||s.submissions[0]?.id],s.selectedRuleset)+note('Nếu dùng để dự giải, chọn thời gian đúng cấu hình giải. 72 mẫu dùng chung một quỹ thời gian. Benchmark không bảo đảm bot đủ thời gian cho cả trận thực tế.')+submit('Chạy trên worker')):empty('Cần nộp bot trước','Tải SDK và nộp source tại tab Nộp bot.'))}${panel('Lịch sử benchmark',jobTable(s,s.jobs.filter(j=>j.kind==='benchmark')))}`;
}
function practice(s) {
  const options=s.submissions.map(x=>[x.id,x.version+' · SDK v'+(x.protocol_version||2)]);
  return `${head('Luyện tập','Ghép hai phiên bản của chính đội bạn; kết quả không tính vào giải.')}${panel('Trận luyện tập mới',options.length?form('practice-form',`<div class="form-grid"><label class="field"><span>Bot Đỏ (đi trước)</span>${select('red_submission_id',options)}</label><label class="field"><span>Bot Xanh</span>${select('blue_submission_id',options)}</label></div>${timeField()}${note('Mỗi bot có quỹ riêng cho cả trận. Chỉ chạy đồng hồ khi đến lượt; không cộng giây sau nước đi.')}${botRulesetField(s,[s.submissions[0]?.id,s.submissions[0]?.id])}<label class="check-field"><input type="checkbox" name="delegate" required>Đội đồng ý server đại diện đối thủ tuyên bố hết giờ sau deadline cứng và khoảng chờ 3 giây.</label>`+submit('Tạo trận luyện tập')):empty('Chưa có bot','Nộp source C++ để thử một trận đầu tiên.'))}${panel('Các trận của đội',jobTable(s,s.jobs.filter(j=>j.kind==='match')))}`;
}
function fixturesTable(s,rows) {
  return rows.length?table(['Trận','Đỏ · Đi trước','Xanh','Trạng thái / kết quả',''],rows.map(f=>`<tr><td>#${f.ordinal}</td><td>${esc(teamName(s,f.red_team_id))}</td><td>${esc(teamName(s,f.blue_team_id))}</td><td>${badge(f.status)}${f.result?`<div class="muted">${esc(resultLabel(f.result,side=>teamName(s,f[side+'_team_id'])))}</div>`:''}</td><td>${link(`${f.status==='completed'?'replay':'arena'}/${f.competition_id}/${f.id}`,f.status==='completed'?'Replay':'Xem trận','small')}${s.user?.role==='admin'&&f.status==='attention'?button('Xem lỗi','diagnostic',`data-fixture="${f.id}"`,'small'):''}</td></tr>`)):empty('Chưa có lịch đấu','Lịch đấu được tạo sau khi ban tổ chức chốt bot.');
}
function competitionSelect(s) {
  return `<div class="filters"><label class="field"><span>Giải đang xem</span>${select('competition-select',[['','Chọn giải đấu'],...s.competitions.map(c=>[c.id,c.title])],s.competition?.id||'',false)}</label>${s.competition?link('competitions/'+s.competition.id,'Thông tin giải','small'):''}</div>`;
}
function competition(s) {
  if(!s.competition) return empty('Chưa chọn giải','Chọn một giải đấu từ danh sách.');
  const c=s.competition,admin=s.user?.role==='admin',own=c.entries.find(e=>e.team_id===s.user?.team_id);
  const actions=admin&&!c.archived_ms?{draft:[['open','Mở đăng ký']],open:[['lock','Chốt bot và tạo lịch']],locked:[['start','Bắt đầu giải']],running:[['pause','Tạm dừng ghép trận']],paused:[['start','Tiếp tục giải']]}[c.status]||[]:[];
  const qualified=s.jobs.filter(j=>j.kind==='benchmark'&&j.status==='completed'&&j.benchmark_summary?.passed&&j.benchmark_summary.samples===72&&j.profile.id===c.config.profile.id&&j.image_id===c.config.image_id&&(j.ruleset?.hash||'')===(c.config.ruleset?.hash||''));
  return `${head(c.title,'Vòng tròn hai lượt · Thắng 3đ · Hòa 1đ · Thua 0đ · Bằng điểm đồng hạng',actions.map(([a,l])=>button(l,'competition-action',`data-command="${a}"`,'primary')).join('')+(admin?competitionTools(c):''))}<div class="competition-summary">${badge(c.archived_ms?"aborted":c.status,c.archived_ms?"Đã lưu trữ":"")}<span>${timeLabel(c.config.profile)}</span><span>${c.entries.length}/${c.config.max_teams} đội</span><span>${c.fixture_counts.completed} trận hoàn tất</span>${c.fixture_counts.attention?badge('attention',c.fixture_counts.attention+' trận cần xử lý'):''}</div>${c.config.ruleset?note('Ruleset add-on · '+c.config.ruleset.definition.name+' · v'+c.config.ruleset.version+' · '+c.config.ruleset.hash.slice(0,12))+(s.user?link('rulesets/'+c.config.ruleset.id,'Chi tiết luật & hướng dẫn bot','small'):''):''}${note(policyLabel(c.config))}${!s.user?note('Bạn đang xem với tư cách khách. Đăng nhập tài khoản đội để chọn bot dự giải.')+link('login','Đăng nhập đội','small'):''}${s.user?.role==='team'&&c.status==='open'?panel(own?'Phiên bản đội đang chọn: '+own.version:'Chọn bot dự giải',qualified.length?form('entry-form',`<label class="field"><span>Benchmark đạt chuẩn của đội</span>${select('qualified',qualified.map(j=>[j.submission_ids[0]+':'+j.id,subName(s,j.submission_ids[0])+' · '+short(j.id)+' · '+date(j.created_unix_ms)]))}</label><label class="check-field"><input name="delegate" type="checkbox" required>Ủy quyền cho server tuyên bố hết giờ sau deadline cứng và khoảng chờ 3 giây.</label>`+submit(own?'Thay bot dự giải':'Đăng ký bot dự giải')+(own?button('Rút bot khỏi giải','withdraw-entry'):'')+note('Bạn có thể thay hoặc rút bot trước khi admin chốt. Sau khi chốt, mọi trận dùng đúng binary đã benchmark.')):empty('Cần benchmark đúng cấu hình giải',`Chạy benchmark với ngân sách ${timeLabel(c.config.profile)} rồi quay lại chọn bot.`)+link('benchmark?'+timeQuery(c.config.profile)+(c.config.ruleset?'&ruleset='+c.config.ruleset.id:''),'Đến benchmark','primary')):''}${panel('Đội dự giải',c.entries.length?table(['Đội','Phiên bản','Chọn lúc',''],c.entries.map(e=>`<tr><td><strong>${esc(e.name)}</strong></td><td>${esc(e.version)}</td><td>${date(e.accepted_ms)}</td><td>${admin&&c.status==='open'?button('Loại khỏi giải','remove-entry',`data-team="${e.team_id}"`,'small'):''}</td></tr>`)):empty('Chưa có đội đăng ký bot'))}${panel('Lịch đấu',fixturesTable(s,s.fixtures),link('standings?competition='+c.id,'Bảng xếp hạng','small'))}`;
}
function competitions(s) {
  if(s.ids[0]) return competition(s);
  const create=s.user?.role==='admin'?panel('Tạo giải mới',form('competition-form',field('Tên giải','title','required minlength="3" maxlength="100"')+`<div class="form-grid">${timeField()}${field('Số đội tối đa','max_teams','required min="2" max="32"','number','16')}</div>`+rulesetField(s,s.selectedRuleset||'',true)+note('Hai lượt đổi màu, xếp theo tổng điểm: thắng 3đ, hòa 1đ, thua 0đ; bằng điểm đồng hạng. Thời gian có thể sửa khi còn bản nháp chưa có đội chọn bot; sau khi mở đăng ký, cấu hình thời gian được giữ cố định.')+submit('Tạo bản nháp'))):'';
  return `${head('Giải đấu','Chọn giải để xem thông tin, đăng ký bot và theo dõi kết quả.')}${create}${s.user?.role==='admin'?`<label class="check-field"><input type="checkbox" name="competition-archived" ${s.competitionArchived?'checked':''}>Xem giải đã lưu trữ</label>`:''}${compCards(s)}`;
}
function standings(s) {
  return `${head('Bảng xếp hạng.','Xếp theo tổng điểm · Thắng 3đ, hòa 1đ, thua 0đ · Bằng điểm đồng hạng.',s.standings?.items.length?button('Xuất CSV','export-standings'):'' )}${competitionSelect(s)}${s.competition?panel(s.competition.title,(s.standings?.provisional?note('Bảng tạm thời: giải còn trận chưa hoàn tất. Trận lỗi hạ tầng không được tính thành hòa hoặc thua.'):'')+(s.standings?.items.length?standingsChart(s.standings,s.user?.team_id):empty('Chưa có đội dự giải'))):empty('Chưa có bảng xếp hạng','Chọn một giải đấu để xem kết quả. Không dùng trận luyện tập để tính hạng.')}`;
}
function schedule(s,live=false) {
  const rows=live?s.fixtures.filter(f=>f.status==='queued'):s.fixtures;
  return `${head(live?'Trực tiếp':'Lịch thi đấu',live?'Mở trận để theo dõi bàn cờ cập nhật tại chỗ.':'Mỗi cặp đội đấu hai lượt và đổi màu.',button('Làm mới','refresh'))}${competitionSelect(s)}${s.competition?panel(s.competition.title,fixturesTable(s,rows)):empty('Chưa có giải đấu','Ban tổ chức sẽ mở giải để các đội đăng ký bot.')}`;
}
function team(s) {
  const t=s.team;
  return `${head(t.name,'Thông tin đội đã đăng ký.',link('change-password','Đổi mật khẩu'))}<div class="real-two-col">${panel('Thông tin đội',`<dl class="detail-list"><div><dt>Tên đội</dt><dd>${esc(t.name)}</dd></div><div><dt>Email đội trưởng</dt><dd>${esc(t.email)}</dd></div><div><dt>Điện thoại</dt><dd>${esc(t.phone||'Chưa cung cấp')}</dd></div><div><dt>Tài khoản</dt><dd>${esc(s.user.username)}</dd></div></dl>${note('Liên hệ ban tổ chức nếu cần thay đổi tên đội hoặc danh sách thành viên sau khi duyệt.')}`)}${panel('Thành viên',table(['Họ và tên','Mã sinh viên'],t.members.map((m,i)=>`<tr><td>${esc(m.name)}${i===0?'<div class="muted">Đội trưởng</div>':''}</td><td class="mono">${esc(m.student_id)}</td></tr>`)))}</div>`;
}
function job(s) {
  const j=s.job; if(!j)return empty('Đang tải job…');
  const r=j.report;
  return `${head((j.kind==='benchmark'?'Benchmark':'Trận luyện tập')+' · '+short(j.id),'Tiến độ và kết quả chạy bot.',j.kind==='match'?link('arena/practice/'+j.id,'Mở bàn cờ','primary'):button('Làm mới','refresh'))}<div id="job-status">${jobDetail(s)}</div>${r?panel('Báo cáo đầy đủ',`<details><summary>Thời gian, cấu hình và thông tin bản build</summary><pre class="report-json">${esc(JSON.stringify(r,null,2))}</pre></details>`,button('Tải JSON','download-report')):''}`;
}
export function jobDetail(s) {
  const j=s.job,r=j?.report;if(!j)return '';
  const groups=(r?.sandbox_metrics||[]).filter(x=>x?.cgroup).map(x=>x.cgroup);
  const maxMetric=items=>{const values=(items||[]).map(x=>x.wall_ms).filter(Number.isFinite);return values.length?metric(Math.max(...values)):'—';};
  const resources=groups.length?stats([['CPU container',metric(groups.reduce((sum,x)=>sum+x.cpu_usage_usec/1000,0)),'code','Tổng CPU các container bot'],['Bộ nhớ cao nhất',(Math.max(...groups.map(x=>x.memory_peak_bytes))/1048576).toFixed(2)+' MiB','grid','Container bot dùng RAM cao nhất'],['Khởi động',maxMetric(r.startup),'clock','Init → ready; không gồm tạo container'],['Biên dịch',maxMetric(r.artifacts),'clock','Số đo lúc build artifact; có thể đã cache']]):'';
  return `${panel('Trạng thái',`<div class="competition-summary">${badge(j.status)}${j.ruleset?badge('attention','Experimental · '+j.ruleset.definition.name):''}<span>${date(j.created_unix_ms)}</span><span>${timeLabel(j.profile)}</span><span>${j.ruleset?'Experimental · protocol v3':'OTT v2 tiêu chuẩn · protocol v2'}</span></div>${s.jobProgress?`<p class="progress-label">${s.jobProgress.completed}/${s.jobProgress.total} mẫu hoàn tất</p>`:''}${j.error?`<div class="form-error visible">${esc(j.error.code)}: ${esc(j.error.detail)}</div>${jobErrorExplanation(j)?note(jobErrorExplanation(j)):""}${j.kind==='benchmark'?link('benchmark?submission='+j.submission_ids[0]+'&'+timeQuery(j.profile)+(j.ruleset?'&ruleset='+j.ruleset.id:''),'Chọn luật & chạy lại','small'):""}`:''}${r?.result?note(resultLabel(r.result)):''}`)}${r?.fault||r?.startup_faults?.length?panel('Chẩn đoán bot',table(['Phe','Giai đoạn','Lỗi'],(r.startup_faults||[r.fault]).map(f=>`<tr><td>${sideName(f.side)}</td><td>${f.stage==='startup'?'Khởi động':'Lượt '+esc(f.turn_id||'—')}</td><td>${esc(resultReasons[f.code]||f.code)}<div class="muted">${esc(f.detail)}</div>${f.action?`<code>${esc(JSON.stringify(f.action))}</code>`:''}</td></tr>`))):''}${r?.turn_wall_ms?stats([['Số mẫu',r.turn_wall_ms.samples,'grid'],['Trung vị',metric(r.turn_wall_ms.median_ms),'clock'],['P95',metric(r.turn_wall_ms.p95_ms),'clock'],['Tối đa',metric(r.turn_wall_ms.max_ms),'clock']]):''}${resources}${groups.length?note('CPU và peak memory là số đo toàn container, bao gồm trusted supervisor; không phải RSS riêng của bot. CPU từng lượt có trong báo cáo JSON.'):''}`;
}
const admin=adminTeams;
function guide(s) {
  const timing=[['Tổng thời gian mỗi đội','Bullet: 1 phút · Đấu thường: 5 phút (mặc định). Chỉ trừ khi đến lượt, không cộng giây.'],['Benchmark','72 mẫu dùng chung một quỹ thời gian của bot; không cấp lại cho mỗi mẫu'],['Deadline','Action phải được worker nhận đầy đủ trước deadline cứng'],['Khoảng chờ','3 giây trước khi server đại diện đối thủ tuyên bố hết giờ; không nhận action muộn'],['Startup / build','2 giây / 30 giây'],['Bot / build RAM','256 MiB / 1.024 MiB; 1 CPU, một process/thread'],['Kết thúc trận · v2','Lặp thế 3 lần, 512 ply hoặc 20 phút: hòa; server dừng / lỗi hạ tầng: không tính kết quả']];
  const steps=[['01 · Viết bot C++17','Giữ bot.cpp ở thư mục gốc ZIP. Bot đọc observation và trả action qua JSON Lines trên stdin/stdout.'],['02 · Test trên worker','Chạy benchmark để nhận median, P95, max, build/startup và provenance. Chọn thời gian đúng giải nếu đăng ký bot dự giải.'],['03 · Chốt & thi đấu','Đội chọn version đã benchmark. Admin chốt lịch; binary được giữ nguyên xuyên suốt giải.']];
  return head('Tài liệu & thể lệ','Luật chơi, hướng dẫn viết bot và giới hạn vận hành.',s.user?.role==='team'?button('Tải starter OTTv2','starter','','primary'):s.user?link('home','Về tổng quan'):link('login','Đăng nhập để tải SDK','primary'))+
    `<div class="real-card-grid">${steps.map(([title,text])=>panel(title,`<p>${text}</p>`)).join('')}</div>`+
    panel('Hướng dẫn viết bot C++17',`<p>Mở từng mục để xem cách đóng gói, đọc input, trả nước đi và thử bot theo giao thức hiện tại.</p><div class="page-actions bot-guide-downloads"><a class="btn secondary" href="/_ui/bot-guide.md" download="OTTV2-BOT-GUIDE.md">Tải hướng dẫn ${icon('download')}</a><a class="btn secondary" href="/_ui/bot-example.cpp" download="bot.cpp">Tải mẫu C++ ${icon('download')}</a><a class="btn secondary" href="/_ui/ottv2-input.jsonl" download="ottv2-input.jsonl">Tải input mẫu ${icon('download')}</a></div>${renderBotGuide(s.botGuide)}`)+
    panel('Ruleset add-on',note('Tính năng thử nghiệm do BTC bật. SDK v2 vẫn dành cho OTTv2 tiêu chuẩn; SDK mở rộng hỗ trợ năng lượng, vùng, cooldown, mẫu đi và Khiên.')+(s.user?link('rulesets','Thư viện luật & nước đi hợp lệ','small')+button('Tải SDK v3 add-on','experimental-starter'):'')+`<p><a href="/api/v1/experimental/guide">Hướng dẫn SDK v3, kỹ năng và timing</a></p>`)+
    panel('Thời gian & tài nguyên',table(['Giới hạn','Quy định'],timing.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`))+note('Đồng hồ trình duyệt chỉ để hiển thị. Worker monotonic clock là nơi quyết định deadline. Python/Codon chưa được bật ở backend hiện tại.'))+
    panel('Quy tắc vận hành bổ sung · v2',note(policyLabel({adjudication:{id:'ottv2-match-v2'}}))+`<p>Áp dụng cho luyện tập và giải mới. Giải cũ giữ thể lệ v1 đã ghim. Deadline cứng và quyền tuyên bố sau 3 giây giữ nguyên.</p>`)+
    panel('Luật OTTv2',`<article class="rules-document" aria-label="Luật chơi OTTv2">${renderRules(s.rules||'Đang tải luật…')}</article>`)+
    `<div class="page-actions"><a class="btn secondary" href="/docs" target="_blank" rel="noopener">HTTP API quản lý nền tảng ${icon('arrow')}</a><a class="btn secondary" href="/api/v1/rules" download="OTTV2-RULES.md">Tải luật Markdown ${icon('download')}</a></div>`;
}

export function page(s) {
  if(['login','register','recover','change-password'].includes(s.route)) return authPage(s);
  let content=s.loading?empty('Đang tải dữ liệu…'):s.error?`${head('Chưa tải được trang.')}<div class="form-error visible">${esc(s.error)}</div>${button('Thử lại','refresh')}`:({rulesets:x=>x.ids?.[0]?addonDetailPage(x):addonPage(x),home,submissions,benchmark,practice,competitions,standings,team,admin,operations:adminOperations,guide,jobs:job,live:x=>schedule(x,true),schedule:x=>schedule(x,false),audit:x=>head('Nhật ký quản trị.','Theo dõi thao tác; không ghi mật khẩu hoặc source.')+panel('Nhật ký',table(['Người thực hiện','Thao tác','Đối tượng','Thời gian'],x.audit.map(a=>`<tr><td class="mono">${esc(a.actor)}</td><td>${esc(a.action)}</td><td class="mono">${esc(a.target)}</td><td>${date(a.created_ms)}</td></tr>`)))}[s.route]?.(s)||'');
  return shell(s,content);
}
